package glitch

import data.glitch_lib

hardcoded_keywords := {"password", "passwd", "pwd", "pass", "secret", "apikey", "token", "key", "credential", "auth", "secret_key", "access_key", "private_key", "secret_token"}

default_credentials := {"admin", "root", "administrator", "changeme", "password"}

check_hardcoded_value(value) {
    value.ir_type == "String"
    regex.match("^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$", value.value)
} else {
    value.ir_type == "String"
    contains_default_credential(value.value)
} else {
    value.ir_type == "String"
    regex.match("^[a-fA-F0-9]{32,}$", value.value)
} else {
    value.ir_type == "String"
    count(value.value) > 0
    not contains_variable_reference(value)
}

contains_default_credential(str) {
    some cred
    default_credentials[cred]
    regex.match(sprintf("(?i).*%s.*", [cred]), str)
}

contains_variable_reference(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name in hardcoded_keywords
    attr.value.ir_type == "String"
    check_hardcoded_value(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded credentials detected - Avoid embedding static secrets in IaC code. (CWE-798)"
    }
}

